import { useEffect, useState, type FormEvent } from 'react'

import { api, login as loginRequest } from './api.generated'
import { resources, type FieldSchema, type ResourceSchema } from './schema.generated'

const TOKEN_KEY = 'core_odoo_token'
const LOGIN_KEY = 'core_odoo_login'

type Row = Record<string, unknown>
type FormValue = string | boolean
type FormValues = Record<string, FormValue>

interface ResourceClient {
  list?: (token: string) => Promise<Row[]>
  read?: (token: string, id: number) => Promise<Row>
  create?: (token: string, values: Record<string, unknown>) => Promise<{ id: number }>
  update?: (token: string, id: number, values: Record<string, unknown>) => Promise<unknown>
  delete?: (token: string, id: number) => Promise<unknown>
}

const clients = api as unknown as Record<string, ResourceClient>

function message(error: unknown): string {
  return error instanceof Error ? error.message : 'Unexpected error'
}

function defaults(resource: ResourceSchema): FormValues {
  return Object.fromEntries(
    resource.fields.map((field) => [field.name, field.type === 'boolean' ? false : '']),
  )
}

function toFormValue(value: unknown): FormValue {
  if (typeof value === 'boolean') return value
  if (value === null || value === undefined || value === false) return ''
  if (typeof value === 'object') return JSON.stringify(value)
  return String(value)
}

function toPayload(resource: ResourceSchema, values: FormValues): Record<string, unknown> {
  const payload: Record<string, unknown> = {}
  for (const field of resource.fields) {
    const value = values[field.name]
    if (field.type === 'boolean') payload[field.name] = Boolean(value)
    else if (field.type.startsWith('number')) payload[field.name] = value === '' ? null : Number(value)
    else payload[field.name] = value === '' ? null : value
  }
  return payload
}

function formatValue(value: unknown): string {
  if (value === null || value === undefined || value === false) return '—'
  if (typeof value === 'boolean') return value ? 'Yes' : 'No'
  if (typeof value === 'object') return JSON.stringify(value)
  return String(value)
}

export default function App(): JSX.Element {
  const [token, setToken] = useState<string | null>(() => localStorage.getItem(TOKEN_KEY))
  const [loginName, setLoginName] = useState<string>(() => localStorage.getItem(LOGIN_KEY) ?? '')

  const handleLogin = (nextToken: string, nextLogin: string): void => {
    localStorage.setItem(TOKEN_KEY, nextToken)
    localStorage.setItem(LOGIN_KEY, nextLogin)
    setToken(nextToken)
    setLoginName(nextLogin)
  }

  const handleLogout = (): void => {
    localStorage.removeItem(TOKEN_KEY)
    localStorage.removeItem(LOGIN_KEY)
    setToken(null)
    setLoginName('')
  }

  if (!token) return <Login onLogin={handleLogin} />
  return <Workspace token={token} loginName={loginName} onLogout={handleLogout} />
}

function Login({ onLogin }: { onLogin: (token: string, login: string) => void }): JSX.Element {
  const [username, setUsername] = useState('admin')
  const [password, setPassword] = useState('admin')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const submit = async (event: FormEvent<HTMLFormElement>): Promise<void> => {
    event.preventDefault()
    setBusy(true)
    setError(null)
    try {
      const accessToken = await loginRequest(username.trim(), password)
      onLogin(accessToken, username.trim())
    } catch (caught) {
      setError(message(caught))
    } finally {
      setBusy(false)
    }
  }

  return (
    <main className="login-shell">
      <div className="login-glow" aria-hidden="true" />
      <section className="login-card">
        <div className="brand-row">
          <div className="brand-mark">CO</div>
          <div>
            <p className="eyebrow">Core Odoo · Odoo 20</p>
            <h1>App</h1>
          </div>
        </div>
        <p className="muted">Sign in with an Odoo user to manage the generated resources.</p>
        <form className="stack" onSubmit={(event) => void submit(event)}>
          <label className="field">
            <span>Login</span>
            <input value={username} onChange={(event) => setUsername(event.target.value)} autoComplete="username" required />
          </label>
          <label className="field">
            <span>Password</span>
            <input type="password" value={password} onChange={(event) => setPassword(event.target.value)} autoComplete="current-password" required />
          </label>
          <button className="btn primary wide" type="submit" disabled={busy}>
            {busy ? 'Signing in…' : 'Sign in'}
          </button>
          {error && <p className="error">{error}</p>}
          <p className="hint">Local demo defaults: admin / admin.</p>
        </form>
      </section>
    </main>
  )
}

function Workspace({
  token,
  loginName,
  onLogout,
}: {
  token: string
  loginName: string
  onLogout: () => void
}): JSX.Element {
  const [active, setActive] = useState(resources[0]?.name ?? '')
  const resource = resources.find((item) => item.name === active) ?? resources[0]

  return (
    <div className="app-shell">
      <header className="topbar">
        <div className="brand-row">
          <div className="brand-mark small">CO</div>
          <div>
            <strong>Core Odoo</strong>
            <p className="muted tiny">Generated CRUD app</p>
          </div>
        </div>
        <nav className="tabs">
          {resources.map((item) => (
            <button key={item.name} className={item.name === active ? 'active' : ''} onClick={() => setActive(item.name)} type="button">
              {item.name}
            </button>
          ))}
        </nav>
        <div className="session">
          <span className="pill">Session: {loginName}</span>
          <button className="btn ghost" onClick={onLogout} type="button">Sign out</button>
        </div>
      </header>
      <main className="content">
        {resource ? <ResourcePanel key={resource.name} token={token} resource={resource} /> : <p className="empty">No resources declared in backend.yaml.</p>}
      </main>
    </div>
  )
}

function ResourcePanel({ token, resource }: { token: string; resource: ResourceSchema }): JSX.Element {
  const client = clients[resource.apiKey] ?? {}
  const canCreate = resource.operations.includes('create') && typeof client.create === 'function'
  const canUpdate = resource.operations.includes('update') && typeof client.update === 'function'
  const canDelete = resource.operations.includes('delete') && typeof client.delete === 'function'
  const [rows, setRows] = useState<Row[]>([])
  const [form, setForm] = useState<FormValues>(() => defaults(resource))
  const [editing, setEditing] = useState<number | null>(null)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const load = async (): Promise<void> => {
    if (typeof client.list !== 'function') {
      setError('The list operation is not enabled for this resource.')
      setLoading(false)
      return
    }
    setLoading(true)
    setError(null)
    try {
      setRows(await client.list(token))
    } catch (caught) {
      setError(message(caught))
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    void load()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [token, resource.name])

  const submit = async (event: FormEvent<HTMLFormElement>): Promise<void> => {
    event.preventDefault()
    setSaving(true)
    setError(null)
    try {
      const values = toPayload(resource, form)
      if (editing === null) {
        if (typeof client.create !== 'function') throw new Error('create is not enabled')
        await client.create(token, values)
      } else {
        if (typeof client.update !== 'function') throw new Error('update is not enabled')
        await client.update(token, editing, values)
      }
      setEditing(null)
      setForm(defaults(resource))
      await load()
    } catch (caught) {
      setError(message(caught))
    } finally {
      setSaving(false)
    }
  }

  const edit = (row: Row): void => {
    const next: FormValues = {}
    for (const field of resource.fields) next[field.name] = toFormValue(row[field.name])
    setEditing(Number(row.id))
    setForm(next)
  }

  const remove = async (id: number): Promise<void> => {
    if (!window.confirm('Delete this record?')) return
    if (typeof client.delete !== 'function') return
    try {
      await client.delete(token, id)
      if (editing === id) {
        setEditing(null)
        setForm(defaults(resource))
      }
      await load()
    } catch (caught) {
      setError(message(caught))
    }
  }

  return (
    <section className="panel">
      <div className="panel-head">
        <div>
          <p className="eyebrow">{resource.model}</p>
          <h2>{resource.name}</h2>
        </div>
        <button className="btn ghost" onClick={() => void load()} type="button" disabled={loading}>Refresh</button>
      </div>

      {canCreate && (
        <form className="form-grid" onSubmit={(event) => void submit(event)}>
          {resource.fields.map((field) => (
            <FieldControl key={field.name} field={field} value={form[field.name]} onChange={(value) => setForm((current) => ({ ...current, [field.name]: value }))} />
          ))}
          <div className="form-actions">
            <button className="btn primary" type="submit" disabled={saving}>
              {saving ? 'Saving…' : editing === null ? 'Create' : 'Save'}
            </button>
            {editing !== null && (
              <button className="btn ghost" type="button" onClick={() => { setEditing(null); setForm(defaults(resource)) }}>Cancel</button>
            )}
          </div>
        </form>
      )}

      {error && <p className="error">{error}</p>}
      {loading ? <p className="empty">Loading…</p> : rows.length === 0 ? (
        <p className="empty">No records yet.</p>
      ) : (
        <div className="table-wrap">
          <table>
            <thead>
              <tr>
                {resource.fields.map((field) => <th key={field.name}>{field.name.replace(/_/g, ' ')}</th>)}
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((row) => (
                <tr key={String(row.id)}>
                  {resource.fields.map((field) => <td key={field.name}>{formatValue(row[field.name])}</td>)}
                  <td className="row-actions">
                    {canUpdate && <button className="btn tiny" onClick={() => edit(row)} type="button">Edit</button>}
                    {canDelete && <button className="btn tiny danger" onClick={() => void remove(Number(row.id))} type="button">Delete</button>}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </section>
  )
}

function FieldControl({
  field,
  value,
  onChange,
}: {
  field: FieldSchema
  value: FormValue
  onChange: (value: FormValue) => void
}): JSX.Element {
  if (field.type === 'boolean') {
    return (
      <label className="field checkbox-field">
        <span>{field.name.replace(/_/g, ' ')}</span>
        <input type="checkbox" checked={Boolean(value)} onChange={(event) => onChange(event.target.checked)} />
      </label>
    )
  }
  return (
    <label className="field">
      <span>{field.name.replace(/_/g, ' ')}{field.required ? ' *' : ''}</span>
      <input
        type={field.type.startsWith('number') ? 'number' : 'text'}
        value={String(value)}
        onChange={(event) => onChange(event.target.value)}
        required={field.required}
      />
    </label>
  )
}
